function simplePlan(raw='A rule with a condition.'){
 const source={id:'pin:governance',role:'pin',reference:{source:'fictional'},text:raw,sha256:pure.frontierHash(raw),characters:raw.length,utf8_bytes:Buffer.byteLength(raw),required_original:false};return pure.buildPeerInputFrontier({connection:{company_id:'fictional',root_sha256:'a'.repeat(64)},heads:[],pinned_team:{},sources:[source]});
}
function output(context,{verdict='Pass',items}={}){
 const base={protocol:context.response_protocol,subject:context.subject,verdict,reason:'SYNTHETIC semantic judgment, not actual native evidence.',blockers:verdict==='Pass'?[]:['Preserve actual unresolved source boundary.'],exhaustive:verdict==='Pass',boundaries_complete:verdict==='Pass',permitted_action:verdict==='Pass'?(context.subject.stage==='review'?'qualify_node':'continue'):'hold'};
 if(context.subject.stage!=='review'){
  if(items)base.items=items;
  else if(context.unit){const provenance=[{source_id:context.unit.source_id,source_sha256:context.unit.source_sha256,range:context.unit.range,core:context.unit.core}],marker=context.unit.mandatory_marker;base.items=[{id:'effect',kind:'rule',text:'SYNTHETIC complete effect; all source semantics retained by fictional assertion.',scope:'*',conditions:'All original conditions remain.',uncertainty:'No real semantic qualification in this fixture.',basis:'SYNTHETIC entire exact supplied fragment.',supports:[],provenance,marker_ids:[]}];if(marker)base.items.push({id:'mandatory',kind:marker.item_kind,text:'SYNTHETIC original claims remain unaccepted; original status '+JSON.stringify(marker.source_status)+' and units/negative evidence/UNKNOWN remain unchanged.',scope:marker.affected_scope,conditions:'All original conditions/counterevidence persist.',uncertainty:'No acceptance, closure, release, unit conversion or complete original history is established.',basis:'SYNTHETIC complete mandatory source fragment and original marker.',supports:[],provenance,marker_ids:[marker.id]});}
  else{const groups=new Map();for(const [slot,child]of context.children.entries())for(const item of child.output.items){if(!groups.has(item.kind))groups.set(item.kind,[]);groups.get(item.kind).push({key:slot+'/'+item.id,item});}base.items=[...groups].map(([kind,children])=>({id:'merged-'+kind,kind,text:'SYNTHETIC complete child effects and interfaces, preserving unaccepted claims and all original status/units/uncertainty.',scope:'*',conditions:'All child conditions and counterevidence preserved.',uncertainty:'Source fixture only; acceptance/closure/release remain unestablished.',basis:'SYNTHETIC equivalent kind-preserving conjunction.',supports:children.map(c=>c.key),provenance:[],marker_ids:[...new Set(children.flatMap(c=>c.item.marker_ids))]}));}
 }return canonical(base);
}
function prepare(f,capture,node,stage='produce'){
 const args={operation_id:f.op(),frontier_id:capture.frontier_id,node_id:node.id,stage},cap=core.prepareOriginalPeerInputFrontier(f.api,args),binding=core.inspectOriginalPeerInputFrontier(cap),native='synthetic-fresh-native-'+f.n;
 const birth={protocol:'peer-input-frontier-original-creation-v1',profile_id:'soloco-input-frontier-readonly-v1',kind:binding.kind,admission_ref:binding.admission_ref,context_sha256:binding.context_sha256,native_id:native,thread_id:native};core.bindOriginalPeerInputFrontierNative(cap,domain.mintSyntheticCreation(f.ledger,birth));const channel=core.originalPeerInputFrontierChannel(cap),header=channel.header();let raw='';for(let offset=0;offset<header.total_characters;offset+=4096)raw+=channel.read({sha256:header.sha256,offset,length:Math.min(4096,header.total_characters-offset)}).text;return {cap,binding,native,channel,header,context:JSON.parse(raw),args};
}
async function finish(f,prepared,options={}){const raw=output(prepared.context,options);prepared.channel.submit({sha256:prepared.header.sha256,content:raw});const drain={protocol:'peer-owned-admitted-task-drain-v1',kind:prepared.binding.kind,admission_ref:prepared.binding.admission_ref,context_sha256:prepared.binding.context_sha256,native_id:prepared.native,thread_id:prepared.native,turn_id:'synthetic-turn',terminal_status:'completed',output:raw,output_sha256:pure.frontierHash(raw),group_absent:null,remote_domain_closed:false};return core.completeOriginalPeerInputFrontier(prepared.cap,domain.mintSyntheticDrain(f.ledger,drain));}

test('exact overlapping UTF-8 units preserve all source occurrences and core bytes',()=>{
 const raw='😀\\"\n a consequential boundary '.repeat(1200),p=simplePlan(raw);assert.ok(p.units.length>2);assert.equal(p.units.map(u=>raw.slice(u.core.offset,u.core.end)).join(''),raw);
 for(const u of p.units){assert.equal(u.text,raw.slice(u.range.offset,u.range.end));assert.ok(Buffer.byteLength(raw.slice(u.core.offset,u.core.end))<=8000);assert.equal(Buffer.from(u.text).toString(),u.text);assert.equal(u.sha256,peerDigest(Object.fromEntries(Object.entries(u).filter(([k])=>!['id','sha256'].includes(k)))));}
 assert.equal(p.manifest.nodes.length,p.units.length*2-1);assert.equal(p.manifest.qualification,'UNQUALIFIED_EXACT_SOURCE_PREPARATION');
});
