test('new nonoverlapping source or truly changed full material retains old UNKNOWN and original limits',t=>{
 for(const changed of [false,true]){const f=fixture(t);seed(f,'control','usage',{model_calls:9,padding:'old exact material'});const cut=f.capture(),manifest=capturedManifest(f,cut),unit=changed?usageUnits(manifest).units[0]:manifest.units.find(u=>u.source_id==='pin:cos_instructions'),cap=core.prepareOriginalPeerInputFrontier(f.api,{operation_id:f.op(),frontier_id:cut.frontier_id,node_id:unit.id,stage:'produce'}),binding=core.inspectOriginalPeerInputFrontier(cap);core.holdOriginalPeerInputFrontier(cap,{error:'Original UNKNOWN remains reserved.'});const oldSlot=get(f,'slots',binding.admission_ref.id.replace(':admission','')),originalAuthority=get(f,'control','origin').value.maintenance;if(changed){const usage=get(f,'control','usage');seed(f,'control','usage',{...usage.value,padding:'A genuinely different complete material body; no claim of semantic independence.'});}
  const cold=new PeerLedger(f.root);t.after(()=>cold.close());const api=core.createPeerInputFrontierMaintenance({ledger:cold,actor}),next=api.capture({operation_id:f.op(),source_instruction:'SYNTHETIC exact changed/nonoverlapping source; unchanged original limits.'}),nextManifest=capturedManifest(f,next),target=usageUnits(nextManifest).units[0],newCap=core.prepareOriginalPeerInputFrontier(api,{operation_id:f.op(),frontier_id:next.frontier_id,node_id:target.id,stage:'produce'});assert.ok(newCap);const authority=get(f,'control','origin').value.maintenance;assert.equal(authority.used_model_calls,originalAuthority.used_model_calls+1);for(const field of ['max_model_calls','max_review_calls','max_frontier_calls','max_frontier_reviews','expires_at'])assert.equal(authority[field],originalAuthority[field]);assert.deepEqual(get(f,'slots',oldSlot.id),oldSlot);assert.equal(oldSlot.value.status,'unknown');assert.ok(nextManifest.mandatory_markers.some(m=>m.source_status==='unknown'));
 }
});
test('malformed null item is retained and rejected after original drain without broad provider catch',async t=>{
 const f=fixture(t),cut=f.capture(),node=f.api.inspect({frontier_id:cut.frontier_id}).nodes[0],p=prepare(f,cut,node),value=JSON.parse(output(p.context));value.items=[null];const raw=canonical(value);p.channel.submit({sha256:p.header.sha256,content:raw});const token=domain.mintSyntheticDrain(f.ledger,{protocol:'peer-owned-admitted-task-drain-v1',kind:p.binding.kind,admission_ref:p.binding.admission_ref,context_sha256:p.binding.context_sha256,native_id:p.native,thread_id:p.native,terminal_status:'completed',output:raw,output_sha256:pure.frontierHash(raw),group_absent:null,remote_domain_closed:false}),result=await core.completeOriginalPeerInputFrontier(p.cap,token),row=get(f,'work_items',result.result_ref.id);assert.equal(result.error,'FRONTIER_INPUT');assert.equal(row.value.text,raw);assert.equal(row.value.output_sha256,pure.frontierHash(raw));assert.equal(get(f,'slots',p.binding.admission_ref.id.replace(':admission','')).value.status,'released');assert.equal(get(f,'control','origin').value.maintenance.used_model_calls,1);unchanged(f,()=>core.prepareOriginalPeerInputFrontier(f.api,{operation_id:f.op(),frontier_id:cut.frontier_id,node_id:node.id,stage:'produce'}),'FRONTIER_NEGATIVE_OR_DUPLICATE');
});
test('all nonobject item values are branded pure validation errors before dereference',()=>{
 const p=simplePlan(),context=pure.peerInputFrontierContext(p,{node_id:p.manifest.root,stage:'produce',authority:{peer_policy:{max_context_bytes:65536}}}).body,valid=JSON.parse(output(context));for(const item of [null,[],false,0,'bad item']){const value={...valid,items:[item]};assert.throws(()=>pure.validatePeerInputFrontierOutput(canonical(value),context),error=>pure.isPeerInputFrontierValidationError(error)&&error.code==='FRONTIER_INPUT');}
});
test('malformed decoded numbers and excessive nesting are branded before canonical copy',()=>{
 const p=simplePlan(),context=pure.peerInputFrontierContext(p,{node_id:p.manifest.root,stage:'produce',authority:{peer_policy:{max_context_bytes:65536}}}).body,valid=JSON.parse(output(context));for(const raw of [canonical(valid).replace('"reason":"SYNTHETIC semantic judgment, not actual native evidence."','"reason":-0'),canonical(valid).replace('"reason":"SYNTHETIC semantic judgment, not actual native evidence."','"reason":1e999'),canonical(valid).replace('"reason":"SYNTHETIC semantic judgment, not actual native evidence."','"reason":'+'['.repeat(80)+'null'+']'.repeat(80))])assert.throws(()=>pure.validatePeerInputFrontierOutput(raw,context),error=>pure.isPeerInputFrontierValidationError(error)&&error.code==='FRONTIER_OUTPUT');
});
test('same-frontier repeated immutable physical occurrences remain separately admissible',async t=>{
 const f=fixture(t),body={kind:'retained-source',status:'current',text:'Exactly repeated immutable source body'},original=seed(f,'work_items','same-body-source',body);seed(f,'work_items','same-body-source',{...body,text:'A genuinely different intervening immutable revision.'});seed(f,'work_items','same-body-source',body);seed(f,'work_items','original-body-handle',{original:ref('work_items',original)});const cut=f.capture(),manifest=capturedManifest(f,cut),sources=manifest.sources.filter(s=>s.reference.family==='work_items'&&s.reference.id==='same-body-source');assert.equal(sources.length,2);const units=sources.map(s=>manifest.units.find(u=>u.source_id===s.id)),p=prepare(f,cut,{id:units[0].id});await finish(f,p);const q=prepare(f,cut,{id:units[1].id});assert.deepEqual(q.binding.logical_source_refs,p.binding.logical_source_refs);assert.notDeepEqual(q.binding.logical_target_ref,p.binding.logical_target_ref);assert.equal((await finish(f,q)).verdict,'Pass');
});
